    "content": "#!/usr/bin/env bash\n# runLocal — clone any repo, install its dependencies, and run it as a plain\n# local process (no cluster, no pod). The only user-facing entrypoint.\nset -euo pipefail\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nLIB_DIR=\"$SCRIPT_DIR/lib\"\n\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/common.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/prereqs.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/config.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/env.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/detect.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/deps.sh\"\n# shellcheck source=/dev/null\nsource \"$LIB_DIR/run.sh\"\n\nRUNLOCAL_VERSION=\"$(cat \"$SCRIPT_DIR/VERSION\" 2>/dev/null || echo dev)\"\n\nusage() {\ncat <<EOF\nrunLocal v$RUNLOCAL_VERSION — clone any repo, install deps, run it as a local service.\n\nUSAGE:\n  run-local.sh [REPO_PATH] [options]      # run a repo on disk (default: cwd)\n  run-local.sh <git-url>   [options]      # clone into ./<name>, then run\n\nOPTIONS:\n  --cmd <cmd>           Override the run command\n  --install-cmd <cmd>   Override the dependency-install command\n  --stack <id>          Force the stack (node|python|go|maven|gradle|rust|\n                        ruby|php|compose|docker|make|procfile)\n  --port <n>            Set the PORT env var passed to the service\n  --env-file <path>     Load env vars from this file (relative to repo root)\n  --no-install          Skip dependency installation\n  --detect-only         Print the detected stack + planned commands, then exit\n  --verbose             Verbose logging\n  -h, --help            Show this help\n\nCONFIG:\n  Drop a .runlocal.yaml at the repo root to override any of the above without\n  CLI flags. See templates/.runlocal.yaml.example.\n\nEXAMPLES:\n  ./run-local.sh ~/code/my-api\n  ./run-local.sh https://github.com/acme/widget.git --port 8080\n  ./run-local.sh . --detect-only\n  ./run-local.sh . --cmd \"npm run dev\" --no-install\nEOF\n}\n\n# resolve_repo <arg> — clone if a git URL, validate if a path. Echoes abs path.\nresolve_repo() {\n    local arg=\"${1:-.}\"\n    if [[ \"$arg\" =~ ^(https?://|git@|ssh://) ]]; then\n        require_cmd git \"Install git\"\n        local name dest\n        name=\"$(basename \"$arg\" .git)\"\n        dest=\"$PWD/$name\"\n        if [[ -d \"$dest/.git\" ]]; then\n            log_info \"Repo already present at $dest\"\n        else\n            log_info \"Cloning $arg -> $dest\"\n            git clone --depth 1 \"$arg\" \"$dest\" >&2 || die \"git clone failed\" 1\n        fi\n        printf '%s\\n' \"$dest\"\n        return 0\n    fi\n    [[ -d \"$arg\" ]] || die \"Path not found: $arg\" 2\n    ( cd \"$arg\" && pwd )\n}\n\nmain() {\n    local repo_arg=\"\" no_install=0 detect_only=0\n    local cli_cmd=\"\" cli_install=\"\" cli_stack=\"\" cli_port=\"\" cli_env=\"\"\n\n    while [[ $# -gt 0 ]]; do\n        case \"$1\" in\n            -h|--help)     usage; exit 0 ;;\n            --verbose)     VERBOSE=1; shift ;;\n            --no-install)  no_install=1; shift ;;\n            --detect-only) detect_only=1; shift ;;\n            --cmd)         cli_cmd=\"${2:?--cmd needs a value}\"; shift 2 ;;\n            --install-cmd) cli_install=\"${2:?--install-cmd needs a value}\"; shift 2 ;;\n            --stack)       cli_stack=\"${2:?--stack needs a value}\"; shift 2 ;;\n            --port)        cli_port=\"${2:?--port needs a value}\"; shift 2 ;;\n            --env-file)    cli_env=\"${2:?--env-file needs a value}\"; shift 2 ;;\n            --)            shift; break ;;\n            -*)            die \"Unknown option: $1 (see --help)\" 2 ;;\n            *)             [[ -z \"$repo_arg\" ]] && repo_arg=\"$1\" || die \"Unexpected argument: $1\" 2; shift ;;\n        esac\n    done\n\n    prereqs_check\n\n    local repo_dir\n    repo_dir=\"$(resolve_repo \"$repo_arg\")\"\n    # For a monorepo with no runnable root, descend into the single subdir app\n    # (or list candidates and bail). Honors an explicit root .runlocal.yaml.\n    narrow_to_app \"$repo_dir\"\n    repo_dir=\"$NARROWED_DIR\"\n    log_info \"Repo: $repo_dir\"\n\n    config_load \"$repo_dir\"\n\n    # CLI flags override config file values.\n    [[ -n \"$cli_cmd\" ]]     && CFG_RUN_CMD=\"$cli_cmd\"\n    [[ -n \"$cli_install\" ]] && CFG_INSTALL_CMD=\"$cli_install\"\n    [[ -n \"$cli_stack\" ]]   && CFG_STACK=\"$cli_stack\"\n    [[ -n \"$cli_port\" ]]    && CFG_PORT=\"$cli_port\"\n    [[ -n \"$cli_env\" ]]     && CFG_ENV_FILE=\"$cli_env\"\n\n    [[ -n \"${CFG_PORT:-}\" && ! \"$CFG_PORT\" =~ ^[0-9]+$ ]] && die \"Invalid --port '$CFG_PORT' — expected an integer\" 2\n\n    local stack\n    stack=\"$(detect_stack \"$repo_dir\")\"\n    [[ \"$stack\" == \"unknown\" ]] && die \"Could not detect a project type in $repo_dir. Set 'stack' + 'run_cmd' in .runlocal.yaml, or pass --stack and --cmd.\" 5\n    log_success \"Detected stack: $stack\"\n\n    env_apply \"$repo_dir\"\n\n    if [[ $detect_only -eq 1 ]]; then\n        local planned\n        planned=\"${CFG_RUN_CMD:-$(run_resolve \"$stack\" \"$repo_dir\" 2>/dev/null || echo '(unresolved — set run_cmd or --cmd)')}\"\n        printf '\\n  stack:        %s\\n  install_cmd:  %s\\n  run_cmd:      %s\\n  port:         %s\\n\\n' \\\n            \"$stack\" \"${CFG_INSTALL_CMD:-<stack default>}\" \"$planned\" \"${CFG_PORT:-<none>}\"\n        exit 0\n    fi\n\n    if [[ $no_install -eq 0 ]]; then\n        deps_install \"$stack\" \"$repo_dir\"\n        log_success \"Dependencies installed\"\n    else\n        log_warn \"Skipping dependency install (--no-install)\"\n        deps_runtime_only \"$stack\" \"$repo_dir\"\n    fi\n\n    # macOS Gatekeeper refuses to exec quarantined native binaries (esbuild/fsevents/*.node),\n    # which a browser-downloaded repo (or its node_modules) inherits — the service then dies at\n    # boot. Strip the attribute across the repo before running. Best-effort; no-op off macOS.\n    # Only downloaded repos carry the flag (git clones and package installs never do), and a\n    # recursive sweep of a big node_modules/venv takes minutes — so check the repo itself first.\n    if [[ \"$(uname -s)\" == \"Darwin\" ]] && command -v xattr >/dev/null 2>&1; then\n        local f flagged=0\n        for f in \"$repo_dir\" \"$repo_dir/package.json\" \"$repo_dir/requirements.txt\" \"$repo_dir/go.mod\" \"$repo_dir/pom.xml\"; do\n            [[ -e \"$f\" ]] && xattr -p com.apple.quarantine \"$f\" >/dev/null 2>&1 && { flagged=1; break; }\n        done\n        if [[ \"$flagged\" == 1 ]]; then\n            xattr -dr com.apple.quarantine \"$repo_dir\" >/dev/null 2>&1 || true\n        fi\n    fi\n\n    run_service \"$stack\" \"$repo_dir\"\n}\n\nmain \"$@\"\n",
